def components(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            cells = set()
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0, c0 = min(y for y,x in cells), min(x for y,x in cells)
            sig = frozenset((y-r0,x-c0) for y,x in cells)
            result.append((color, cells, sig, min(cells)))
    return bg, result

def transform(grid):
    bg, objs = components(grid)
    out = [row[:] for row in grid]
    # When the same non-background shape occurs in two colors, recolor the
    # earlier scanned instance to the later instance's color.
    for i, (color, cells, sig, pos) in enumerate(objs):
        matches = [o for o in objs[i+1:] if o[2] == sig and o[0] != color]
        if matches:
            target_color = matches[0][0]
            for r, c in cells:
                out[r][c] = target_color
            break
    return out

