 "content": "from collections import deque

def components(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    seen, objs = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen: continue
            cells = set(); q = deque([(r,c)]); seen.add((r,c))
            while q:
                y,x=q.popleft(); cells.add((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            objs.append((color,cells))
    return bg,objs

def transform(grid):
    _, objs = components(grid)
    out=[row[:] for row in grid]
    # A short straight component is an instance of the longer line motif;
    # recolor it with the motif's color.
    candidates=[]
    for i,(color,cells) in enumerate(objs):
        r0=min(r for r,c in cells); r1=max(r for r,c in cells)
        c0=min(c for r,c in cells); c1=max(c for r,c in cells)
        if len(cells)==c1-c0+1 and r0==r1:
            n=len(cells)
            for j,(other,ocells) in enumerate(objs):
                if i==j or color==other: continue
                # Candidate lies as a subsegment of a longer horizontal line.
                rows={r for r,c in ocells}
                for rr in rows:
                    cols=sorted(c for r,c in ocells if r==rr)
                    runs=[]
                    for cc in cols:
                        if not runs or cc>runs[-1][-1]+1: runs.append([cc])
                        else: runs[-1].append(cc)
                    if any(len(run)>n and n<=len(run) for run in runs):
                        candidates.append((n,i,other))
    if candidates:
        _, idx, target=max(candidates)
        for r,c in objs[idx][1]: out[r][c]=target
    return out

