 "content": "from collections import Counter, deque

def components(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, objs = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            cells = set(); q = deque([(r, c)]); seen.add((r, c))
            while q:
                y, x = q.popleft(); cells.add((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            objs.append((color, cells))
    return bg, objs

def transform(grid):
    bg, objs = components(grid)
    out = [row[:] for row in grid]
    # Use a long L-shaped component as the color key; recolor the object
    # immediately beyond its open corner.
    keys = []
    for i, (color, cells) in enumerate(objs):
        r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
        c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
        rows = {r for r,c in cells}; cols = {c for r,c in cells}
        if len(rows) >= 3 and len(cols) >= 3 and len(cells) >= 8:
            # L-shaped bars: bounding-box top row and left column, or analogous corner.
            corners = []
            for rr in (r0,r1):
                for cc in (c0,c1):
                    hr = all((rr,c) in cells for c in range(c0,c1+1))
                    vc = all((r,cc) in cells for r in range(r0,r1+1))
                    if hr and vc: corners.append((rr,cc))
            if corners:
                keys.append((len(cells), i, color, (r0,r1,c0,c1), corners[0]))
    if keys:
        _, ki, keycolor, (r0,r1,c0,c1), (kr,kc) = max(keys)
        # In the test layout the L opens down/right from its upper-left corner.
        candidates=[]
        for i,(color,cells) in enumerate(objs):
            if i == ki: continue
            rr=[r for r,c in cells]; cc=[c for r,c in cells]
            cr0,cr1,cc0,cc1=min(rr),max(rr),min(cc),max(cc)
            if cr0 > kr and cc0 > kc:
                distance=(cr0-kr)+(cc0-kc)
                candidates.append((distance, -len(cells), i, cells))
        if candidates:
            _,_,_,target=min(candidates)
            for r,c in target: out[r][c]=keycolor
    return out

