        r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
        c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        corners=[]
        for rr in (r0,r1):
            for cc in (c0,c1):
                horizontal=all((rr,c) in cells for c in range(c0,c1+1))
                vertical=all((r,cc) in cells for r in range(r0,r1+1))
                if horizontal and vertical: corners.append((rr,cc))
        # Exclude filled rectangles (which satisfy the corner test four times).
        if len(corners)==1 and len(cells) < (r1-r0+1)*(c1-c0+1):
