    right = kc == c0
    candidates=[]
    for i,(color,cells) in enumerate(objs):
        if i==key_i: continue
        rr=[r for r,c in cells]; cc=[c for r,c in cells]
        cr0,cr1,cc0,cc1=min(rr),max(rr),min(cc),max(cc)
        if (cr0 > kr if down else cr1 < kr) and (cc0 > kc if right else cc1 < kc):
            distance=abs((cr0 if down else cr1)-kr)+abs((cc0 if right else cc1)-kc)
            candidates.append((distance,-len(cells),i,cells))
