def components(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            cells=set(); q=deque([(r,c)]); seen.add((r,c))
            while q:
                y,x=q.popleft(); cells.add((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            objs.append((color,cells))
    return bg,objs

def transform(grid):
    _,objs=components(grid); out=[row[:] for row in grid]
    # A shorter straight motif takes the color of a longer parallel motif.
    # Prefer the longest target with a strictly longer same-orientation exemplar.
    matches=[]
    for i,(color,cells) in enumerate(objs):
        rs={r for r,c in cells}; cs={c for r,c in cells}
        if len(rs)==1:
            n=len(cells); direction='h'
        elif len(cs)==1:
            n=len(cells); direction='v'
        else:
            continue
        if n<2: continue
        for j,(other,othercells) in enumerate(objs):
            if i==j or color==other: continue
            ors={r for r,c in othercells}; ocs={c for r,c in othercells}
            if direction=='h' and len(ors)==1 and len(othercells)>n:
                matches.append((n,-len(othercells),i,other))
            if direction=='v' and len(ocs)==1 and len(othercells)>n:
                matches.append((n,-len(othercells),i,other))
    if matches:
        _,_,idx,target=max(matches)
        for r,c in objs[idx][1]: out[r][c]=target
    return out

