        r0,r1=min(r for r,c in cells),max(r for r,c in cells)
        c0,c1=min(c for r,c in cells),max(c for r,c in cells)
        corners=[]
        for rr in (r0,r1):
            for cc in (c0,c1):
                if all((rr,c) in cells for c in range(c0,c1+1)) and all((r,cc) in cells for r in range(r0,r1+1)):
                    corners.append((rr,cc))
        if len(corners)==1 and len(cells)<(r1-r0+1)*(c1-c0+1):
            keys.append((len(cells),i,color,corners[0]))
