def components(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col==bg or (r,c) in seen: continue
            cells=set(); q=deque([(r,c)]); seen.add((r,c))
            while q:
                y,x=q.popleft(); cells.add((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
                        seen.add((yy,xx)); q.append((yy,xx))
            objs.append((col,cells))
    return bg,objs

def transform(grid):
    bg,objs=components(grid); out=[row[:] for row in grid]
    # isolated colored dot is the fill color; fill the rectangular area enclosed
    # between parallel same-color line fragments when there is a clear bounded gap.
    dots=[(col,next(iter(cells))) for col,cells in objs if len(cells)==1]
    if not dots: return out
    fill=dots[0][0]
    # identify horizontal line fragments enclosing a rectangular block
    h,w=len(grid),len(grid[0])
    for r in range(h):
        runs=[]
        c=0
        while c<w:
            if grid[r][c]!=bg:
                cc=c
                while cc+1<w and grid[r][cc+1]==grid[r][c]: cc+=1
                if cc-c+1>=2: runs.append((c,cc,grid[r][c]))
                c=cc+1
            else: c+=1
        for a in range(len(runs)):
            for b in range(a+1,len(runs)):
                x0,x1,col=runs[a]; y0,y1,col2=runs[b]
                if col==col2 and y0>x1+1:
                    for rr in range(r-1,-1,-1):
                        if grid[rr][x0]==col and grid[rr][x1]==col:
                            for yy in range(rr+1,r):
                                for xx in range(x0+1,x1):
                                    if grid[yy][xx]==bg: out[yy][xx]=fill
                            return out
    return out

